package com.bassbeats.player;

import android.app.*;import android.content.*;import android.media.*;import android.media.session.*;import android.net.Uri;import android.os.*;import android.graphics.BitmapFactory;import android.provider.Settings;import android.view.KeyEvent;

public class PlaybackService extends Service {
 public static final String PLAY="com.bassbeats.player.PLAY",TOGGLE="com.bassbeats.player.TOGGLE",NEXT="com.bassbeats.player.NEXT",PREV="com.bassbeats.player.PREV";
 MediaPlayer player; MediaSession session; String title="BASS BEATS",artist="Offline Player"; int notif=42;
 @Override public void onCreate(){super.onCreate();NotificationChannel ch=new NotificationChannel("bass_playback","Music playback",NotificationManager.IMPORTANCE_LOW);ch.setDescription("BASS BEATS playback controls");((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(ch);session=new MediaSession(this,"BASS BEATS");session.setCallback(new MediaSession.Callback(){@Override public void onPlay(){resume();}@Override public void onPause(){pause();}@Override public void onSkipToNext(){sendBroadcast(new Intent("com.bassbeats.player.SKIP_NEXT"));}@Override public void onSkipToPrevious(){sendBroadcast(new Intent("com.bassbeats.player.SKIP_PREV"));}@Override public void onMediaButtonEvent(Intent intent){KeyEvent e=intent.getParcelableExtra(Intent.EXTRA_KEY_EVENT);if(e!=null&&e.getAction()==KeyEvent.ACTION_DOWN){if(e.getKeyCode()==KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE)toggle();else if(e.getKeyCode()==KeyEvent.KEYCODE_MEDIA_PLAY)resume();else if(e.getKeyCode()==KeyEvent.KEYCODE_MEDIA_PAUSE)pause();} }});session.setFlags(MediaSession.FLAG_HANDLES_MEDIA_BUTTONS|MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS);session.setActive(true);}
 @Override public int onStartCommand(Intent i,int flags,int startId){if(i==null)return START_NOT_STICKY;String a=i.getAction();if(PLAY.equals(a)){title=i.getStringExtra("title");artist=i.getStringExtra("artist");String u=i.getStringExtra("uri");try{if(player!=null){player.release();player=null;}player=new MediaPlayer();player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());player.setDataSource(this,Uri.parse(u));player.setOnPreparedListener(mp->{mp.start();updateSession();showNotification();});player.setOnCompletionListener(mp->{pause();});player.prepareAsync();}catch(Exception e){stopSelf();}}else if(TOGGLE.equals(a))toggle();else if(NEXT.equals(a))sendBroadcast(new Intent("com.bassbeats.player.SKIP_NEXT"));else if(PREV.equals(a))sendBroadcast(new Intent("com.bassbeats.player.SKIP_PREV"));return START_NOT_STICKY;}
 void toggle(){if(player!=null&&player.isPlaying())pause();else resume();}void resume(){if(player!=null)try{player.start();showNotification();updateSession();}catch(Exception ignored){}}void pause(){if(player!=null&&player.isPlaying())player.pause();showNotification();updateSession();}
 void updateSession(){if(session==null)return;long pos=player==null?0:player.getCurrentPosition(),dur=player==null?0:player.getDuration();session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,title).putString(MediaMetadata.METADATA_KEY_ARTIST,artist).putLong(MediaMetadata.METADATA_KEY_DURATION,dur).build());session.setPlaybackState(new PlaybackState.Builder().setActions(PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_PLAY_PAUSE|PlaybackState.ACTION_SKIP_TO_NEXT|PlaybackState.ACTION_SKIP_TO_PREVIOUS|PlaybackState.ACTION_SEEK_TO).setState(player!=null&&player.isPlaying()?PlaybackState.STATE_PLAYING:PlaybackState.STATE_PAUSED,pos,1f).build());}
 PendingIntent action(String a,int code){Intent i=new Intent(this,PlaybackService.class);i.setAction(a);return PendingIntent.getService(this,code,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 void showNotification(){boolean on=player!=null&&player.isPlaying();Notification.Builder b=new Notification.Builder(this,"bass_playback").setContentTitle(title==null?"Unknown title":title).setContentText(artist==null?"Unknown artist":artist).setSmallIcon(android.R.drawable.ic_media_play).setVisibility(Notification.VISIBILITY_PUBLIC).setOngoing(on).addAction(new Notification.Action.Builder(android.R.drawable.ic_media_previous,"Previous",action(PREV,1)).build()).addAction(new Notification.Action.Builder(on?android.R.drawable.ic_media_pause:android.R.drawable.ic_media_play,on?"Pause":"Play",action(TOGGLE,2)).build()).addAction(new Notification.Action.Builder(android.R.drawable.ic_media_next,"Next",action(NEXT,3)).build()).setDeleteIntent(action(TOGGLE,4)).setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0,1,2));startForeground(notif,b.build());}
 @Override public void onDestroy(){if(player!=null){player.release();player=null;}if(session!=null){session.setActive(false);session.release();}stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}@Override public android.os.IBinder onBind(Intent i){return null;}
}
